'use client';

import React, { useState } from 'react';
import { styleTemplates, getStyleTemplate } from '@/config/styles';
import { StyleTemplateId } from '@/types/styles';
import { Check, X } from 'lucide-react';
import { TEMPLATE_DECORATOR_SUGGESTIONS } from '@/config/styles';

interface StyleTemplateSelectorProps {
  value: StyleTemplateId;
  onChange: (templateId: StyleTemplateId) => void;
  pillarColor?: string;
  currentDecoratorConfig?: any; // Optional: current decorator config to show sync status
}

// Template categories
const TEMPLATE_CATEGORIES: Record<string, StyleTemplateId[]> = {
  'Modern': ['glassmorphism', 'cyberpunk', 'holographic', 'vaporwave'],
  'Minimal': ['minimal', 'swiss-minimal', 'gradient-mesh'],
  'Bold': ['brutalist', 'bold', 'geometric'],
  'Elegant': ['elegant', 'editorial', 'organic'],
  'Tech': ['isometric-3d', 'tech-data', 'modern'],
  'Creative': ['abstract-art', 'pattern', 'playful'],
};

export function StyleTemplateSelector({ value, onChange, pillarColor = '#00E5FF', currentDecoratorConfig }: StyleTemplateSelectorProps) {
  const [activeCategory, setActiveCategory] = useState('Modern');

  // Get decorator suggestions for current template
  const currentTemplateSuggestions = TEMPLATE_DECORATOR_SUGGESTIONS[value] || {};

  // Helper to check if a decorator is enabled in the current config
  const isDecoratorEnabled = (decoratorKey: string): boolean => {
    if (decoratorKey === 'border') return currentDecoratorConfig?.border?.enabled ?? false;
    if (decoratorKey === 'cornerAccents') return currentDecoratorConfig?.cornerAccents?.enabled ?? false;
    if (decoratorKey === 'accentLines') return currentDecoratorConfig?.accentLines?.enabled ?? false;
    return false;
  };

  // Check if current decorators match template suggestions
  const getDecoratorSyncStatus = (decoratorKey: string): 'synced' | 'mismatch' | 'neutral' => {
    const suggested = currentTemplateSuggestions[decoratorKey]?.enabled;
    const current = isDecoratorEnabled(decoratorKey);

    if (suggested === undefined || current === undefined) return 'neutral';
    return suggested === current ? 'synced' : 'mismatch';
  };

  return (
    <div className="space-y-3">
      <label className="block text-sm font-medium text-gray-200">
        Style Template
      </label>

      {/* Category Tabs */}
      <div className="flex gap-2 overflow-x-auto pb-2">
        {Object.keys(TEMPLATE_CATEGORIES).map((category) => (
          <button
            key={category}
            onClick={() => setActiveCategory(category)}
            className={`px-3 py-1 rounded-full text-xs font-medium whitespace-nowrap transition-colors ${
              activeCategory === category
                ? 'bg-[var(--pillar-color)] text-black'
                : 'bg-gray-700 text-gray-400 hover:bg-gray-600'
            }`}
            style={{
              '--pillar-color': pillarColor,
            } as React.CSSProperties}
          >
            {category}
          </button>
        ))}
      </div>

      {/* Template Grid */}
      <div className="grid grid-cols-2 gap-2">
        {TEMPLATE_CATEGORIES[activeCategory].map((id) => {
          const template = styleTemplates[id];
          if (!template) return null;

          // Get decorator sync status for this template
          const borderSync = getDecoratorSyncStatus('border');
          const cornerSync = getDecoratorSyncStatus('cornerAccents');
          const accentSync = getDecoratorSyncStatus('accentLines');

          return (
            <button
              key={id}
              onClick={() => onChange(id as StyleTemplateId)}
              className={`
                relative p-3 rounded-lg border-2 transition-all text-left
                ${value === id
                  ? 'border-[var(--pillar-color)] bg-[var(--pillar-color)]10'
                  : 'border-gray-700 bg-gray-800/50 hover:border-gray-600'
                }
              `}
              style={{
                '--pillar-color': pillarColor,
              } as React.CSSProperties}
            >
              <div className="font-medium text-sm text-gray-100 capitalize">
                {id}
              </div>
              <div className="text-xs text-gray-400 mt-1">
                {template.layout.position}
              </div>

              {/* Decorator Sync Indicators */}
              {currentDecoratorConfig && (
                <div className="flex items-center gap-1 mt-2 flex-wrap">
                  {template.decorators.border && (
                    <div className={`flex items-center gap-0.5 px-1.5 py-0.5 rounded text-[9px] ${
                      borderSync === 'synced' ? 'bg-green-500/20 text-green-400' :
                      borderSync === 'mismatch' ? 'bg-yellow-500/20 text-yellow-400' :
                      'bg-gray-700 text-gray-400'
                    }`}>
                      {borderSync === 'synced' ? <Check className="w-2.5 h-2.5" /> : borderSync === 'mismatch' ? <X className="w-2.5 h-2.5" /> : null}
                      Border
                    </div>
                  )}
                  {template.decorators.cornerAccents && (
                    <div className={`flex items-center gap-0.5 px-1.5 py-0.5 rounded text-[9px] ${
                      cornerSync === 'synced' ? 'bg-green-500/20 text-green-400' :
                      cornerSync === 'mismatch' ? 'bg-yellow-500/20 text-yellow-400' :
                      'bg-gray-700 text-gray-400'
                    }`}>
                      {cornerSync === 'synced' ? <Check className="w-2.5 h-2.5" /> : cornerSync === 'mismatch' ? <X className="w-2.5 h-2.5" /> : null}
                      Corners
                    </div>
                  )}
                  {template.decorators.accentLines && (
                    <div className={`flex items-center gap-0.5 px-1.5 py-0.5 rounded text-[9px] ${
                      accentSync === 'synced' ? 'bg-green-500/20 text-green-400' :
                      accentSync === 'mismatch' ? 'bg-yellow-500/20 text-yellow-400' :
                      'bg-gray-700 text-gray-400'
                    }`}>
                      {accentSync === 'synced' ? <Check className="w-2.5 h-2.5" /> : accentSync === 'mismatch' ? <X className="w-2.5 h-2.5" /> : null}
                      Lines
                    </div>
                  )}
                </div>
              )}

              {value === id && (
                <div
                  className="absolute top-2 right-2 w-2 h-2 rounded-full"
                  style={{ backgroundColor: pillarColor }}
                />
              )}
            </button>
          );
        })}
      </div>

      {/* Sync Info */}
      {currentDecoratorConfig && (
        <div className="mt-2 p-2 bg-white/5 rounded-lg">
          <div className="text-xs text-white/60 mb-1">Template Decorators:</div>
          <div className="flex gap-1 flex-wrap">
            {currentTemplateSuggestions.border?.enabled && (
              <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] ${
                isDecoratorEnabled('border') ? 'bg-green-500/20 text-green-400' : 'bg-gray-700 text-gray-400'
              }`}>
                <Check className="w-2.5 h-2.5" /> Border
              </span>
            )}
            {currentTemplateSuggestions.cornerAccents?.enabled && (
              <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] ${
                currentDecoratorConfig?.cornerAccents?.enabled ? 'bg-green-500/20 text-green-400' : 'bg-gray-700 text-gray-400'
              }`}>
                <Check className="w-2.5 h-2.5" /> Corners
              </span>
            )}
            {currentTemplateSuggestions.accentLines?.enabled && (
              <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] ${
                currentDecoratorConfig?.accentLines?.enabled ? 'bg-green-500/20 text-green-400' : 'bg-gray-700 text-gray-400'
              }`}>
                <Check className="w-2.5 h-2.5" /> Lines
              </span>
            )}
            {(!currentTemplateSuggestions.border?.enabled && !currentTemplateSuggestions.cornerAccents?.enabled && !currentTemplateSuggestions.accentLines?.enabled) && (
              <span className="text-xs text-gray-500">No decorators recommended</span>
            )}
          </div>
        </div>
      )}
    </div>
  );
}